default_title, default_message = g["greetings"].get(preset, ("", ""))
if preset == "christmas" and gl == "ru":
    default_title, default_message = "С Рождеством Христовым!", "Мир в доме, любовь и радость в сердце."
elif preset == "christmas" and gl == "en":
    default_message = "Peace in your home, love and joy in your heart."
if chosen == "royal":
    default_title, default_message = "", ""
    st.caption("Надпись Merry Christmas уже входит в этот шаблон. Дополнительное пожелание можно добавить ниже." if ru else
               "Merry Christmas lettering is part of this template. An extra personal message is optional below.")
text_key = f"{gl}_{preset}_{chosen == 'royal'}"
st.caption("Оставьте готовый текст или напишите своё пожелание. Его можно менять после генерации."
           if ru else "Keep the suggested text or write your own. You can edit it after generation.")
name = st.text_input(t["name"], max_chars=60, key="recipient")
title = st.text_input(t["heading"], value=default_title, max_chars=100, key="heading_" + text_key)
message = st.text_area(t["message"], value=default_message,
                       max_chars=250, key="message_" + text_key)
size, horizontal, vertical = 100, 50, 50
if not original:
    with st.expander(t["adjust"]):
        size = st.slider(t["size"], 60, 100, 100, key="size")
        horizontal = st.slider(t["horizontal"], 0, 100, 50, key="horizontal")
        vertical = st.slider(t["vertical"], 0, 100, 50, key="vertical")

if uploaded and (st.session_state.get("result") or st.session_state.get("scene_versions")) and st.button(t["reset"],
                          help="Удалить текущее фото и результат, чтобы загрузить другое фото." if ru else
                               "Remove the current photo and result to upload a different photo."):

    for key in list(st.session_state):
        if key.startswith(("upload_", "photo_", "result", "check_", "scene_")) or key in {
            "recipient", "size", "horizontal", "vertical"
        }:
            del st.session_state[key]
    st.session_state["upload_revision"] = revision + 1
    st.rerun()

st.caption(t["privacy"])


@st.cache_resource
def supported_characters():
    with TTFont(str(FONT_DIR / "DejaVuSans.ttf")) as selected_font:
        return set(selected_font.getBestCmap())


if not uploaded:
    st.session_state.pop("result", None)
    st.info("Чтобы создать открытку, сначала загрузите фотографию в разделе 2." if ru else
            "To create your card, first upload a photo in section 2.")
    st.button(t["create"], type="primary", disabled=True, key="create_needs_photo")
    st.stop()

data = uploaded.getvalue()
digest = hashlib.sha256(data).hexdigest()
signature = (digest, original, selected, category, preset, gl, title, message, name, size, horizontal, vertical, card_format)
if st.session_state.get("result_signature") != signature:
    st.session_state.pop("result", None)

try:
    if st.session_state.get("photo_digest") != digest:
        st.session_state.pop("photo_image", None)
        st.session_state.pop("check_signature", None)
        st.session_state["photo_image"] = load_photo(data)
        st.session_state["photo_digest"] = digest
    photo = st.session_state["photo_image"]
    characters = name + title + message
    if any(ord(character) not in supported_characters() for character in characters if character != "\n"):
        st.error(t["unsupported"])
        st.stop()
    if scene_mode:
        if not scene_available or not scene_authorized:
            st.warning("Фото загружено. Для создания сцены введите тестовый пароль выше."
                       if ru else "Your photo is uploaded. Enter the test password above to create the scene.")
            if st.button(t["create"], type="primary", key="scene_locked"):
                st.error("Доступ ещё не подтверждён. Нажмите «Подтвердить пароль» в разделе загрузки фото."
                         if ru else "Access is not confirmed yet. Click Confirm password in the upload section.")
            st.stop()
        scene_editor(photo, digest, scene, lang, title, message, name, api_key, t)
        st.stop()
    if original:
        card = render_original(photo, selected, title, message, name, christmas=preset == "christmas")
    else:
        card = render_frame(photo, selected, title, message, name, size, horizontal, vertical)
    preview = card.copy()
    preview.thumbnail((320, 400), Image.Resampling.LANCZOS)
    st.image(preview, caption=t["preview"], width=320)
    if st.button(t["create"], type="primary"):
        with st.spinner(t["creating"]):
            result = {
                "png": encode_image(card, "PNG"),
                "jpg": encode_image(card, "JPEG"),
            }
            if card_format == "animated":
                result["mp4"] = animate(card, selected)
            st.session_state["result"] = result
            st.session_state["result_signature"] = signature
            st.session_state["result_filename"] = (
                f"Magic_Greetings_{selected}_{gl}_{datetime.now():%Y%m%d_%H%M%S}"
            )
    if st.session_state.get("result"):
        st.success(t["ready"])
        result = st.session_state["result"]
        if "mp4" in result:
            st.video(result["mp4"])
        for extension, contents in result.items():
            mime = {"png": "image/png", "jpg": "image/jpeg", "mp4": "video/mp4"}[extension]
            st.download_button(
                t["download"] + " " + extension.upper(), contents,
                st.session_state["result_filename"] + "." + extension, mime,
                on_click="ignore",
            )
except ScenePending:
    watch_scene_request(lang == "ru")
except PhotoError as error:
    st.error(t["errors"].get(str(error), "Не удалось подготовить открытку." if lang == "ru"
                                else "Could not prepare the card."))
except requests.Timeout:
    st.session_state.pop("scene_resume", None)
    st.error("Сервис изображений не ответил вовремя. Фото и текст остались в этой вкладке. "
             "Обработка у сервиса могла продолжиться; автоматический повтор отключён. "
             "Новая попытка отправит новый запрос."
             if lang == "ru" else
             "The image service timed out. Your photo and message remain in this tab. "
             "Processing may have continued at the provider; automatic retries are disabled. "
             "A new attempt will send a new request.")
except (requests.RequestException, KeyError, IndexError, ValueError) as error:
    st.session_state.pop("scene_resume", None)
    if scene_mode:
        response = getattr(error, "response", None)
        LOGGER.error("Scene request or rendering failed (%s, HTTP %s)",
                                          type(error).__name__, getattr(response, "status_code", None))
        status = getattr(response, "status_code", None)
        try:
            code = response.json().get("error", {}).get("code", "") if response is not None else ""
        except (ValueError, AttributeError):
            code = ""
        if status == 401:
            reason = "Сервис не принимает API-ключ. Владельцу сайта нужно проверить подключение." if lang == "ru" else "The service rejected the API key. The site owner needs to check the connection."
        elif status == 429 and code in {"insufficient_quota", "billing_hard_limit_reached"}:
            reason = "Недостаточно доступного баланса API. Владельцу сайта нужно проверить оплату и лимиты." if lang == "ru" else "The API balance or billing limit needs attention from the site owner."
        elif status == 429:
            reason = "Сервис перегружен. Подождите немного перед новой попыткой." if lang == "ru" else "The service is busy. Please wait before trying again."
        elif status in (400, 403, 404):
            reason = "Сервис отклонил запрос. Владельцу сайта нужно проверить настройки и доступ к модели." if lang == "ru" else "The service rejected the request. The site owner needs to check model access and settings."
        elif status and status >= 500:
            reason = "Временный сбой сервиса изображений. Фото и текст остались в этой вкладке." if lang == "ru" else "The image service encountered a temporary error. Your photo and message remain in this tab."
        else:
            reason = "Не удалось прочитать результат сервиса. Фото и текст остались в этой вкладке." if lang == "ru" else "The image service result could not be read. Your photo and message remain in this tab."
        st.error(reason)
    else:
        st.error("Не удалось подготовить открытку." if lang == "ru" else "Could not prepare the card.")
except Exception as error:
    st.session_state.pop("scene_resume", None)
    if scene_mode:
        LOGGER.error("Card preparation failed (%s)", type(error).__name__)
        st.error("Не удалось подготовить открытку к скачиванию." if lang == "ru"
                 else "Could not prepare the card for download.")
    else:
        st.error("Не удалось подготовить открытку." if lang == "ru" else "Could not prepare the card.")
